<?php use App\Services\Catalog; ?>
<section class="page-banner"><div class="container"><p class="eyebrow">PLANIFICA TU ENTRENAMIENTO</p><h1>Tu semana<br>en la cancha.</h1><p>Consulta los horarios vigentes y encuentra tu grupo de entrenamiento.</p></div></section>
<section class="container section"><form class="schedule-filter" method="get" action="<?= e(config()['base_path']) ?>/index.php"><input type="hidden" name="r" value="horarios"><div><label for="categoria">Categoría</label><select name="categoria" id="categoria"><option value="0">Todas las categorías</option><?php foreach($categories as $cat): ?><option value="<?= e($cat['id']) ?>" <?= $category==(int)$cat['id']?'selected':'' ?>><?= e($cat['nombre']) ?></option><?php endforeach; ?></select></div><div><label for="dia">Día de entrenamiento</label><select name="dia" id="dia"><option value="0">Todos los días</option><?php foreach(Catalog::days() as $k=>$label): ?><option value="<?= e($k) ?>" <?= $day===$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Consultar horarios</button><a class="text-link" href="<?= e(url('horarios')) ?>">Limpiar filtros</a></form>
<div class="section-head"><h2>Agenda de entrenamientos</h2><p><?= count($schedules) ?> <?= count($schedules)===1?'horario disponible':'horarios disponibles' ?></p></div>
<?php if(!$schedules): ?><div class="empty-editorial"><h3><?= $category||$day?'No hay entrenamientos para esta selección.':'Aún no hay horarios publicados.' ?></h3><p><?= $category||$day?'Prueba con otro día o categoría.':'La academia publicará aquí los días, las horas y los lugares de entrenamiento.' ?></p></div><?php endif; ?>
<div class="week-agenda"><?php foreach(Catalog::days() as $dayNumber=>$label): $daily=array_filter($schedules,fn($s)=>(int)$s['dia']===$dayNumber);if(!$daily)continue; ?><section class="day-group"><div class="day-heading"><h3><?= e($label) ?></h3><span><?= count($daily) ?> <?= count($daily)===1?'sesión':'sesiones' ?></span></div><div><?php foreach($daily as $slot): ?><article class="session-row"><div class="session-time"><strong><?= e(substr($slot['hora_inicio'],0,5)) ?></strong><span>a <?= e(substr($slot['hora_fin'],0,5)) ?></span></div><div><h3><?= e($slot['nombre']) ?></h3><p><?= e($slot['lugar']) ?></p></div><span class="badge">Vigente</span></article><?php endforeach; ?></div></section><?php endforeach; ?></div>
<div class="section-head category-heading"><div><p class="eyebrow">FORMACIÓN POR ETAPAS</p><h2>Nuestras categorías</h2></div></div><div class="category-grid"><?php foreach($categories as $cat): ?><article class="category"><h3><?= e($cat['nombre']) ?></h3><p><?= e($cat['descripcion']) ?></p><a class="text-link" href="<?= e(url('horarios',['categoria'=>$cat['id']])) ?>">Consultar este grupo</a></article><?php endforeach; ?></div><?php if(!$categories): ?><p class="empty">Las categorías se mostrarán cuando estén habilitadas por la academia.</p><?php endif; ?></section>
